import sys
class MockPip:
    def install(self, pkg):
        raise SystemExit("error: externally-managed-environment. This environment is externally managed. See PEP 668.")
pip = MockPip()
try:
    pip.install("requests")
except SystemExit as e:
    sys.stderr.write(str(e) + "\n")
    sys.exit(1)
